"""Algorithm 2 — Address decoding by the unique-parent sign test.

Given any primitive Pythagorean triple, recover the unique word of Berggren moves
that produces it from (3,4,5). The whole procedure rests on a single linear map

    P(a, b, c) = (a + 2b - 2c, 2a + b - 2c, -2a - 2b + 3c)

which satisfies  P(A.v) = (a, -b, c),  P(B.v) = (a, b, c),  P(C.v) = (-a, b, c).
Since genuine events have strictly positive legs, the position of the minus sign
in P(t) identifies the move that produced t, and flipping that sign back yields
the parent. Each step strictly decreases the hypotenuse, so the loop terminates.
"""

from __future__ import annotations

from math import gcd
from typing import List, Tuple

Triple = Tuple[int, int, int]
ROOT: Triple = (3, 4, 5)


def parent_map(t: Triple) -> Triple:
    """The universal undo map P."""
    a, b, c = t
    return (a + 2 * b - 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)


def parent_and_move(t: Triple) -> Tuple[Triple, str]:
    """Unique parent of t and the move that produced it."""
    if t == ROOT:
        raise ValueError("the root (3,4,5) has no parent")
    x, y, z = parent_map(t)
    if y < 0:
        return (x, -y, z), "A"
    if x < 0:
        return (-x, y, z), "C"
    return (x, y, z), "B"


def address(t: Triple) -> str:
    """The unique address word of a primitive event (leftmost move applied first)."""
    if not (t[0] > 0 and t[1] > 0 and t[2] > 0 and t[0] ** 2 + t[1] ** 2 == t[2] ** 2):
        raise ValueError(f"{t} is not an event")
    if gcd(t[0], t[1]) != 1:
        raise ValueError(f"{t} is not primitive, so it is not a node of the tree")
    letters: List[str] = []
    cur = t
    while cur != ROOT:
        cur, s = parent_and_move(cur)
        letters.append(s)
    return "".join(reversed(letters))


def proper_time_from_root(t: Triple) -> int:
    """Discrete proper time between the root and t: the length of its address."""
    return len(address(t))


if __name__ == "__main__":
    tests: List[Triple] = [(3, 4, 5), (5, 12, 13), (21, 20, 29), (15, 8, 17),
                           (119, 120, 169), (1343, 2976, 3265), (4059, 4060, 5741)]
    for t in tests:
        w = address(t)
        print(f"{str(t):>22}  address = {w or 'e':<8} proper time = {proper_time_from_root(t)}")
